#include <bits/stdc++.h>
using namespace std; using ll=long long; using Graph=vector<unsigned>; using Sig=array<ll,6>; using St=array<ll,4>;
void ck(bool b,string s){if(!b)throw runtime_error(s);}
struct Profile{ vector<ll> h; vector<vector<ll>> s,e; };
Profile prof(const Graph&T){int n=T.size(),N=1<<n;Profile P{vector<ll>(N),vector<vector<ll>>(N,vector<ll>(n)),vector<vector<ll>>(N,vector<ll>(n))};P.h[0]=1;for(int S=1;S<N;S++){for(int v=0;v<n;v++)if(S>>v&1){int U=S^(1<<v);if(!U)P.s[S][v]=P.e[S][v]=1;else for(int w=0;w<n;w++)if(U>>w&1){if(T[v]>>w&1)P.s[S][v]+=P.s[U][w];else P.e[S][v]+=P.e[U][w];}P.h[S]+=P.s[S][v];}}return P;}
Sig sig(const Graph&T,int r){auto P=prof(T);int F=(1<<T.size())-1;ll Q=0,L=0,C=0;for(int S=0;S<=F;S++){C+=P.h[S]*P.h[F^S];if(S>>r&1){Q+=P.s[S][r]*P.h[F^S];L+=P.e[S][r]*P.h[F^S];}}return {P.h[F],P.e[F][r],P.s[F][r],Q,L,C};}
St state(const Graph&T,int r){auto P=prof(T);int F=(1<<T.size())-1;ll R=0;for(int S=0;S<=F;S++)if(S>>r&1)R+=P.s[S][r]*P.h[F^S];return{P.h[F],P.e[F][r],R,P.h[F^(1<<r)]};}
Graph graph(int n,unsigned mask){Graph T(n);int k=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,k++){if(mask>>k&1)T[i]|=1<<j;else T[j]|=1<<i;}return T;}
Graph sew(Graph A,int a,const Graph&B,int b){int n=A.size(),m=B.size();for(int i=0;i<n;i++)A[i]|=((1u<<m)-1)<<n;for(auto x:B)A.push_back(x<<n);A[a]^=1<<(n+b);A[n+b]|=1<<a;return A;}
St step(St s,Sig a){auto[h,e,R,d]=s;auto[H,E,S,Q,L,C]=a;return {H*h-S*e+L*R,E*d,C*R-Q*d,H*d};}
struct Hash{size_t operator()(const St&s)const{size_t h=0;for(ll x:s)h=(h*1000003)^hash<ll>{}(x);return h;}};
struct Result{vector<St> states;int depth;vector<int>missing;};
Result closure(int M,const vector<Sig>&bank){unordered_map<St,int,Hash> dist;vector<St> q;St initial{1,1,1,1};dist[initial]=0;q.push_back(initial);set<int>hits{1};int depth=0;for(size_t p=0;p<q.size();p++){St s=q[p];if(s[0]+s[2]-s[3]>M)continue;for(auto a:bank){St z=step(s,a);if(z[0]>M)continue;ck(z[0]>=s[0]&&z[2]-z[3]>=2*(s[2]-s[3]),"monotonicity");if(dist.count(z))continue;int dep=dist[s]+1;dist[z]=dep;depth=max(depth,dep);ck((1LL<<(dep-1))<=z[0],"depth bound");q.push_back(z);hits.insert(z[0]);}}vector<St>positive;for(auto[h,e,R,d]:q)positive.push_back({h,R-d,d-e,d});sort(positive.begin(),positive.end());vector<int>missing;for(int n=1;n<=M;n+=2)if(!hits.count(n))missing.push_back(n);return{positive,depth,missing};}
ll walkIE(const Graph&T){int n=T.size(),N=1<<n;ll ans=0;for(int S=1;S<N;S++){vector<ll>d(n);for(int i=0;i<n;i++)if(S>>i&1)d[i]=1;for(int j=1;j<n;j++){vector<ll>e(n);for(int i=0;i<n;i++)if(d[i])for(int k=0;k<n;k++)if((S>>k&1)&&(T[i]>>k&1))e[k]+=d[i];d=e;}ll z=accumulate(d.begin(),d.end(),0LL);ans+=((n-__builtin_popcount((unsigned)S))%2?-z:z);}return ans;}
ll cycles(const Graph&T){int n=T.size(),N=1<<n;vector<vector<ll>>dp(N,vector<ll>(n));dp[1][0]=1;for(int S=1;S<N;S++)for(int v=0;v<n;v++)if(dp[S][v])for(int w=0;w<n;w++)if(!(S>>w&1)&&(T[v]>>w&1))dp[S|(1<<w)][w]+=dp[S][v];ll c=0;for(int v=1;v<n;v++)if(T[v]&1)c+=dp[N-1][v];return c;}
Graph gadget(unsigned L){int m=0;for(unsigned z=L-1;z;z>>=1)m++;Graph T(m+1);for(int i=0;i<m;i++){int x=i+1;if((L-1)>>i&1)T[x]|=1;else T[0]|=1<<x;for(int j=i+1;j<m;j++)T[x]|=1<<(j+1);}return T;}
Graph opposite(Graph T){unsigned full=(1<<T.size())-1;for(size_t i=0;i<T.size();i++)T[i]^=full^(1<<i);return T;}
Graph graft(Graph T,vector<int>E,const Graph&G,int r){int n=T.size(),m=G.size();Graph A=T;for(int i=0;i<n;i++)A[i]|=((1<<m)-1)<<n;for(auto row:G)A.push_back(row<<n);for(int x:E){A[x]^=1<<(n+r);A[n+r]|=1<<x;}return A;}
int main(int argc,char**argv){string base=argc>1?argv[1]:".";ofstream out(base+"/literal-profiles.csv");int graphs=0,roots=0;for(int n=1;n<=5;n++)for(unsigned mask=0;mask<(1u<<(n*(n-1)/2));mask++){auto T=graph(n,mask);graphs++;auto P=prof(T);for(int r=0;r<n;r++)if(P.s.back()[r]==1){auto s=state(T,r);out<<s[0]<<","<<s[1]<<","<<s[2]<<","<<s[3]<<"\n";roots++;}}out.close();ck(graphs==1099&&roots==1695,"literal source inventory");int sharp=0;ofstream rows(base+"/sharp-graphs.txt");for(int j=1;j<=3;j++){int x=(1<<j)+1;Graph V=sew(Graph{0},0,gadget(1<<j),0);int r=1,n=V.size();V=sew(V,r,Graph{0},0);r=n;ck(state(V,r)==St{2*x-1,x-1,2*x,x},"actual sharp source");Graph T=sew(V,r,Graph{0},0);int a=V.size();for(int kind=0;kind<2;kind++){Graph L=T;int end=a;if(kind){end=L.size();L=sew(L,a,Graph{0},0);}Graph F=graft(L,{r,end},opposite(V),r);ll H=kind?34*x*x-6*x+1:15*x*x-2*x;ck(prof(F).h.back()==H&&walkIE(F)==H&&cycles(F)==2,"literal sharp graft");rows<<j<<" "<<(kind?'M':'N')<<" "<<H;for(auto v:F)rows<<" "<<v;rows<<"\n";sharp++;}}cout<<"{\"status\":\"PASS\",\"labelled_graphs\":"<<graphs<<",\"start_one_roots\":"<<roots<<",\"sharp_graphs\":"<<sharp<<"}\n";}
